  const unsafeNewLocation = command === 'NEW'
    && /[\u0000-\u001F\u007F-\u009F\u2028\u2029]/u.test(rawParts[1] || '');
  return typeof body.phone === 'string'
    && phone.length > 0
    && phone.length <= 20
    && typeof body.providerMessageId === 'string'
    && providerMessageId.length > 0
    && providerMessageId.length <= 100
    && typeof body.smsText === 'string'
    && smsText.length > 0
    && smsText.length <= 500
    && !unsafeNewLocation;
})() }}

