=={{ (() => {
  const command = $('Prepare command').item.json.command;
  if (command === 'NEW') return $('Prepare NEW contact guidance').item.json.mediator_reply;
  if (command === 'UPDATE') {
    const u = $('Prepare UPDATE').item.json;
    return 'Update for ' + u.case_id + ' saved. The record keeper has been alerted.';
  }
  if (command === 'SUMMARY') return $('Prepare masked SUMMARY').first().json.summary;
  if (command === 'STATUS') {
    const caseRow = $('Find case for STATUS').first().json;
    const caseId = $('Prepare STATUS request').item.json.case_id;
    const allowedStatuses = ['INTAKE LOGGED', 'UNDER REVIEW', 'UNDER MEDIATION', 'FOLLOW-UP', 'CLOSED'];
    const allowedUrgencies = ['NORMAL', 'URGENT'];
    const status = String(caseRow.status ?? '').trim().toUpperCase();
    const urgency = String(caseRow.urgency ?? '').trim().toUpperCase();
    const safeDate = value => {
      const text = String(value ?? '').trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return '';
      const [year, month, day] = text.split('-').map(Number);
      const date = new Date(Date.UTC(year, month - 1, day));
      return date.getUTCFullYear() === year
        && date.getUTCMonth() === month - 1
        && date.getUTCDate() === day
        ? text
        : '';
    };
    const lines = ['Case: ' + caseId];
    if (allowedStatuses.includes(status)) lines.push('Status: ' + status);
    if (allowedUrgencies.includes(urgency)) lines.push('Urgency: ' + urgency);
    const nextFollowUp = safeDate(caseRow.next_follow_up_date);
    if (nextFollowUp) lines.push('Next follow-up: ' + nextFollowUp);
    return lines.join('\n');
  }
  if (command === 'HELP') return 'Commands: NEW, UPDATE, SUMMARY, STATUS, or HELP.';
  return 'Command not recognized. Send HELP.';
})() }}

