    '2. Record Party A and Party B perspectives separately and neutrally.',
    '3. Record the triggering incident, previous related incidents, and earlier resolution attempts.',
    '4. Record any agreement, whether each party accepted it, and the next follow-up date.',
    '5. Record confidentiality and safety notes, including what may or may not be shared.'
  ];
  if (c.category === 'FAMILY') {
    steps.push('6. Confirm that participation is voluntary and whether separate conversations are needed.');
  } else {
    steps.push('6. Confirm which community groups or representatives are involved and who may speak for them.');
  }
  if (c.confidentiality === 'HIGH') {
    steps.push('7. Use Party A and Party B codes. Keep names and phone numbers only in Identifying Details.');
  }
  if (c.urgency === 'URGENT') {
    steps.push((c.confidentiality === 'HIGH' ? '8.' : '7.') + ' Confirm contact with both designated urgent contacts and record what information was shared.');
  }
  return steps.join('\n');
})() }}

